import{_ as a,a0 as r,w as i,s as p,I as s,x as e,a1 as n,A as o,ao as d}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const T=JSON.parse('{"title":"使用Linux的lsblk命令列出塊設備信息 | LCTT x X-CMD","titleTemplate":false,"description":"使用Linux的lsblk命令列出塊設備信息 | LCTT (201407) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用Linux的lsblk命令列出塊設備信息 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用Linux的lsblk命令列出塊設備信息 | LCTT (201407) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201407/20140617 How to use Linux lsblk Command to List Block Device Information","title":"使用Linux的lsblk命令列出塊設備信息","tag":"201407","desc":""},"relativePath":"201407/20140617 How to use Linux lsblk Command to List Block Device Information.md","filePath":"[post].md"}'),b={name:"201407/20140617 How to use Linux lsblk Command to List Block Device Information.md"};function m(u,l,k,x,g,f){const t=r("Link");return i(),p("div",null,[l[14]||(l[14]=s("h1",{id:"使用linux的lsblk命令列出塊設備信息",tabindex:"-1"},[e("使用Linux的lsblk命令列出塊設備信息 "),s("a",{class:"header-anchor",href:"#使用linux的lsblk命令列出塊設備信息","aria-label":"Permalink to “使用Linux的lsblk命令列出塊設備信息”"},"​")],-1)),l[15]||(l[15]=s("p",null,[s("strong",null,"lsblk"),e("（列出塊設備）命令用於列出所有可用塊設備的信息，但是，它"),s("strong",null,"不會列出RAM盤的信息"),e("。塊設備有硬盤，閃存盤，CD-ROM等等。")],-1)),l[16]||(l[16]=s("h3",{id:"如何安裝lsblk",tabindex:"-1"},[e("如何安裝lsblk "),s("a",{class:"header-anchor",href:"#如何安裝lsblk","aria-label":"Permalink to “如何安裝lsblk”"},"​")],-1)),s("p",null,[l[1]||(l[1]=e("lsblk命令包含在util-linux-ng包中，現在該包改名為util-linux。這個包帶了幾個其它工具，如dmesg。要安裝lsblk，請在",-1)),n(t,{href:"ftp://ftp.kernel.org/pub/linux/utils/util-linux/"},{default:o(()=>[...l[0]||(l[0]=[e("此處",-1)])]),_:1}),l[2]||(l[2]=e("下載util-linux包。",-1))]),l[17]||(l[17]=d(`<h3 id="fedora中安裝lsblk" tabindex="-1">Fedora中安裝lsblk <a class="header-anchor" href="#fedora中安裝lsblk" aria-label="Permalink to “Fedora中安裝lsblk”">​</a></h3><p>Fedora用户可以通過以下方法來安裝該包：</p><pre><code>$ sudo yum install util-linux-ng
</code></pre><p>該命令有幾個選項：</p><h3 id="默認選項" tabindex="-1">默認選項 <a class="header-anchor" href="#默認選項" aria-label="Permalink to “默認選項”">​</a></h3><p>lsblk命令默認情況下將以樹狀列出所有塊設備。打開終端，並輸入以下命令：</p><pre><code>$ lsblk
</code></pre><p>輸出如下：</p><p><img src="http://linoxide.com/wp-content/uploads/2014/03/lsblk-default.jpg" alt="lsblk default"></p><p>7個欄目名稱如下：</p><p><strong>NAME</strong> : 這是塊設備名。</p><p><strong>MAJ:MIN</strong> : 本欄顯示主要和次要設備號。</p><p><strong>RM</strong> : 本欄顯示設備是否可移動設備。注意，在本例中設備sdb和sr0的RM值等於1，這説明他們是可移動設備。</p><p><strong>SIZE</strong> : 本欄列出設備的容量大小信息。例如298.1G表明該設備大小為298.1GB，而1K表明該設備大小為1KB。</p><p><strong>RO</strong> : 該項表明設備是否為只讀。在本案例中，所有設備的RO值為0，表明他們不是隻讀的。</p><p><strong>TYPE</strong> :本欄顯示塊設備是否是磁盤或磁盤上的一個分區。在本例中，sda和sdb是磁盤，而sr0是隻讀存儲（rom）。（LCTT譯註，此處sr0的RO項沒有標記為1，可能存在一些錯誤？）</p><p><strong>MOUNTPOINT</strong> : 本欄指出設備掛載的掛載點。</p><h3 id="列出所有設備" tabindex="-1">列出所有設備 <a class="header-anchor" href="#列出所有設備" aria-label="Permalink to “列出所有設備”">​</a></h3><p>默認選項不會列出所有空設備。要查看這些空設備，請使用以下命令：</p><pre><code>$ lsblk -a
</code></pre><p>該選項將列出所有設備，包括空設備在內。</p><p><img src="http://linoxide.com/wp-content/uploads/2014/03/lsblk-bytes-sda.png" alt="lsblk bytes sda"></p><h3 id="列出設備權限和屬主" tabindex="-1">列出設備權限和屬主 <a class="header-anchor" href="#列出設備權限和屬主" aria-label="Permalink to “列出設備權限和屬主”">​</a></h3><p>lsblk命令也可以用於列出一個特定設備的擁有關係，同時也可以列出組和模式。可以通過以下命令來獲取這些信息：</p><pre><code>$ lsblk -m
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/03/lsblk-permissions.png" alt="lsblk  permissions"></p><h3 id="列出指定設備" tabindex="-1">列出指定設備 <a class="header-anchor" href="#列出指定設備" aria-label="Permalink to “列出指定設備”">​</a></h3><p>該命令也可以只獲取指定設備的信息。這可以通過在提供給lsblk命令的選項後指定設備名來實現。例如，你可能對了解以字節顯示你的磁盤驅動器大小比較感興趣，那麼你可以通過運行以下命令來實現：</p><pre><code>$ lsblk -b /dev/sda
</code></pre><p>或者，以下命令等同：</p><pre><code>$ lsblk --bytes /dev/sda
</code></pre><h3 id="以列表形式列出不帶頭的設備" tabindex="-1">以列表形式列出不帶頭的設備 <a class="header-anchor" href="#以列表形式列出不帶頭的設備" aria-label="Permalink to “以列表形式列出不帶頭的設備”">​</a></h3><p>你也可以組合幾個選項來獲取指定的輸出。例如，你也許想要以列表格式列出設備，而不是默認的樹狀格式。你可能也對移除不同欄目名稱的標題感興趣。可以將兩個不同的選項組合，以獲得期望的輸出，命令如下：</p><pre><code>$ lsblk -nl
</code></pre><p>或者，你可以使用下面的長選項，它們也能給出相同的輸出。</p><pre><code>$ lsblk --noheadings --list
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/03/lsblk-no-header-and-list.png" alt="lsblk no header and list"></p><h3 id="列出scsi設備" tabindex="-1">列出SCSI設備 <a class="header-anchor" href="#列出scsi設備" aria-label="Permalink to “列出SCSI設備”">​</a></h3><p>要獲取SCSI設備的列表，你只能使用-S選項。該選項是大寫字母S，不能和-s選項混淆，該選項是用來以顛倒的順序打印依賴的。</p><pre><code>$ lsblk -S
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/03/lsblk-SCSI-devices.png" alt=""></p><p>lsblk列出SCSI設備，而-s是逆序選項（LCTT譯註：將設備和分區的組織關係逆轉過來顯示），其將給出如下輸出。輸入命令：</p><pre><code>$ lsblk -s
</code></pre><p>或者</p><pre><code>$ lsblk --inverse
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/03/lsblk-inverse.png" alt=""></p><p>你可以使用lsblk來獲取關於你的塊設備的更多信息，自己把它試着顯示出來吧！</p><hr>`,48)),s("p",null,[l[4]||(l[4]=e("via: ",-1)),n(t,{href:"http://linoxide.com/linux-command/linux-lsblk-command/"},{default:o(()=>[...l[3]||(l[3]=[e("http://linoxide.com/linux-command/linux-lsblk-command/",-1)])]),_:1})]),s("p",null,[l[7]||(l[7]=e("譯者：",-1)),n(t,{href:"https://github.com/GOLinux"},{default:o(()=>[...l[5]||(l[5]=[e("GOLinux",-1)])]),_:1}),l[8]||(l[8]=e(" 校對：",-1)),n(t,{href:"https://github.com/wxy"},{default:o(()=>[...l[6]||(l[6]=[e("wxy",-1)])]),_:1})]),s("p",null,[l[11]||(l[11]=e("本文由 ",-1)),n(t,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...l[9]||(l[9]=[e("LCTT",-1)])]),_:1}),l[12]||(l[12]=e(" 原創翻譯，",-1)),n(t,{href:"http://linux.cn/"},{default:o(()=>[...l[10]||(l[10]=[e("Linux中國",-1)])]),_:1}),l[13]||(l[13]=e(" 榮譽推出",-1))])])}const L=a(b,[["render",m]]);export{T as __pageData,L as default};
